<script lang="ts">
 import {onDestroy} from "svelte";import {reportEditorDirty} from "./editor-drafts";
 export let editorId="";
 import {uid,today,type Project} from './model';import {saveMeterDocument,type MeterDocument} from './meter-documents';import {displayDate} from './date-format';import {translator} from './i18n';import RecordToolbar from './RecordToolbar.svelte';import {Plus,Trash2,Users,Save,Check,X} from '@lucide/svelte';
 export let project:Project;export let kind:MeterDocument['kind'];export let initial:MeterDocument|null=null;export let onapply:(p:Project)=>void;export let onedit:(d:MeterDocument)=>void;export let onclose:()=>void;
 let draft=initial?structuredClone(initial):null,selected='',error='';$:t=translator(project.settings.language);$:locked=draft?.state==='applied';$:documents=project.meter_documents.filter(d=>d.kind===kind);$:current=documents.find(d=>d.id===selected);$:available=project.meters.filter(m=>kind==='initial'||kind==='status'||m.scope===kind);
 function create(){onedit({id:uid(),number:String(project.meter_documents.length+1),date:today(),period:project.settings.period,kind,state:'draft',comment:'',rows:[]});}
 function add(){const meter=available.find(m=>!draft?.rows.some(r=>r.meter_id===m.id));if(draft&&meter)draft.rows=[...draft.rows,{id:uid(),meter_id:meter.id,value:'',active:meter.active}];}
 function fill(){if(draft)draft.rows=[...draft.rows,...available.filter(m=>m.active&&!draft!.rows.some(r=>r.meter_id===m.id)).map(m=>({id:uid(),meter_id:m.id,value:'',active:m.active}))];}
 function save(post=false,close=false){if(!draft)return;try{const next=saveMeterDocument(project,draft,post);onapply(next);draft=structuredClone(next.meter_documents.find(d=>d.id===draft!.id)!);error='';savedDraft=JSON.stringify(draft);reportEditorDirty(editorId,false);if(close)onclose();}catch(e){error=e instanceof Error?e.message:String(e);}}
 let savedDraft=JSON.stringify(draft);
 $:reportEditorDirty(editorId,!!draft&&(!project.meter_documents.some(d=>d.id===draft!.id)||JSON.stringify(draft)!==savedDraft));
 onDestroy(()=>reportEditorDirty(editorId,false));
</script>
<div class="meter-documents">{#if error}<p class="alert error" role="alert">{error}</p>{/if}
{#if !draft}<RecordToolbar language={project.settings.language} selected={!!current} onadd={create} onedit={()=>current&&onedit(structuredClone(current))} oncopy={()=>{if(current)onedit({...structuredClone(current),id:uid(),number:String(project.meter_documents.length+1),state:'draft',rows:current.rows.map(r=>({...r,id:uid()}))});}} onrefresh={()=>selected=''} onpost={()=>{if(current)try{onapply(saveMeterDocument(project,current,true));error='';}catch(e){error=String(e);}}} canPost={current?.state==='draft'}/><table><thead><tr><th>{t('Дата','Data')}</th><th>{t('Номер','Număr')}</th><th>{t('Период','Perioada')}</th><th>{t('Комментарий','Comentariu')}</th><th>{t('Статус','Stare')}</th></tr></thead><tbody>{#each documents as doc}<tr class:selected={selected===doc.id} class:attention-row={doc.state==='draft'} onclick={()=>selected=doc.id} ondblclick={()=>onedit(structuredClone(doc))}><td>{displayDate(doc.date,project)}</td><td>{doc.number}</td><td>{doc.period}</td><td>{doc.comment}</td><td>{doc.state==='applied'?t('Проведён','Aplicat'):t('Черновик','Ciornă')}</td></tr>{/each}</tbody></table>
{:else}<fieldset disabled={locked}><div class="document-header"><label>{t('Дата','Data')}<input type="date" bind:value={draft.date}/></label><label>{t('Номер','Număr')}<input bind:value={draft.number}/></label><label>{t('Период','Perioada')}<input type="month" bind:value={draft.period}/></label></div><div class="toolbar"><button type="button" class="button secondary" onclick={add}><Plus size={16}/>{t('Добавить','Adaugă')}</button><button type="button" class="button secondary" onclick={fill}><Users size={16}/>{t('Заполнить','Completează')}</button><button type="button" class="button secondary" onclick={()=>{if(draft)draft.rows=[];}}><Trash2 size={16}/>{t('Очистить','Golește')}</button></div>
<div class="table-wrap"><table><thead><tr><th>№</th><th>{t('Прибор учёта','Contor')}</th><th>{t('Лицевой счёт','Cont personal')}</th><th>{kind==='status'?t('Подключён','Conectat'):t('Показание','Index')}</th><th></th></tr></thead><tbody>{#each draft.rows as row,i}<tr><td>{i+1}</td><td><select bind:value={row.meter_id}>{#each available as meter}<option value={meter.id}>{meter.label} · {meter.serial_number}</option>{/each}</select></td><td>{project.accounts.find(a=>a.id===project.meters.find(m=>m.id===row.meter_id)?.account_id)?.number||'—'}</td><td>{#if kind==='status'}<input type="checkbox" aria-label={t('Подключён','Conectat')} bind:checked={row.active}/>{:else}<input aria-label={t('Показание строки ','Indexul rândului ')+(i+1)} bind:value={row.value}/>{/if}</td><td><button type="button" class="icon-button" aria-label={t('Удалить строку','Elimină rândul')} onclick={()=>{if(draft)draft.rows=draft.rows.filter(r=>r.id!==row.id);}}><Trash2 size={16}/></button></td></tr>{/each}</tbody></table></div><label>{t('Комментарий','Comentariu')}<input bind:value={draft.comment}/></label></fieldset><footer>{#if !locked}<button class="button" onclick={()=>save(true,true)}><Check size={16}/>{t('Провести и закрыть','Aplică și închide')}</button><button class="button secondary" onclick={()=>save()}><Save size={16}/>{t('Сохранить','Salvează')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>{/if}</div>
<style>.meter-documents{display:flex;flex-direction:column;gap:12px;padding:12px}fieldset{border:0;padding:0;display:flex;flex-direction:column;gap:12px;min-width:0}.document-header{display:flex;gap:12px}label{display:flex;flex-direction:column;gap:6px}.toolbar,footer{display:flex;gap:8px;flex-wrap:wrap}footer{justify-content:flex-end;padding-top:14px}table{width:100%;border-collapse:collapse}th,td{padding:8px;text-align:left}th{background:#80808020}td select,td input:not([type=checkbox]){width:100%;min-width:100px;box-sizing:border-box}.selected{background:#489bcb30}</style>
